{
  "diagnosis": "The agent often chooses a plausible drug but misses the preferred first-line or safer option when a specific interacting drug or comorbidity is present. Successful cases show that the correct choice is usually the one with both the right indication and the lowest interaction/worsening risk. Four narrowly applicable reusable skills are proposed to encode these conditional distinctions without memorizing answers.",
  "edits": [
    {
      "id": "immunosuppressant-choice-in-autoimmune-hepatitis-with-hypertension",
      "all_terms": [
        "autoimmune hepatitis",
        "high blood pressure"
      ],
      "any_terms": [
        "joint pain",
        "yellow eyes",
        "yellow skin",
        "borderline high blood pressure"
      ],
      "rule": "When autoimmune hepatitis is suspected and the patient has elevated blood pressure or hypertension, prefer a corticosteroid with lower systemic hypertensive effect over other immunosuppressants or unrelated drugs; avoid choosing a drug that is not used for autoimmune hepatitis or that can worsen hypertension."
    },
    {
      "id": "anticoagulation-for-prosthetic-heart-valve-with-clopidogrel",
      "all_terms": [
        "prosthetic heart valves",
        "clopidogrel"
      ],
      "any_terms": [
        "shortness of breath",
        "ankle swelling",
        "prosthetic valve"
      ],
      "rule": "When a patient has prosthetic heart valves and is already taking clopidogrel, choose a vitamin K antagonist anticoagulant for valve-related thromboembolism prevention rather than an antiplatelet, antidepressant, or direct oral anticoagulant unless a specific contraindication is documented."
    },
    {
      "id": "avoid-cyp-interaction-with-lisdexamfetamine-for-obsessive-social-anxiety",
      "all_terms": [
        "lisdexamfetamine"
      ],
      "any_terms": [
        "obsessive thoughts",
        "social anxiety",
        "social interactions",
        "compulsive behaviors"
      ],
      "rule": "When obsessive thoughts or social anxiety symptoms occur in a patient taking lisdexamfetamine, prefer an SSRI with lower CYP450 interaction risk for these symptoms rather than a tricyclic, anticholinergic, or another SSRI with higher interaction potential."
    },
    {
      "id": "complement-inhibitor-choice-for-complement-mediated-disease-on-azathioprine",
      "all_terms": [
        "azathioprine",
        "complement-mediated"
      ],
      "any_terms": [
        "dark urine",
        "shortness of breath",
        "fatigue"
      ],
      "rule": "When a complement-mediated rare disease is suspected in a patient already taking azathioprine, choose the established first-line complement inhibitor for that presentation rather than an antifungal or a second-line complement inhibitor, unless the first-line agent is contraindicated."
    }
  ]
}
